// A story event's dedicated "game over" step, e.g. ev42043100_30 in ev42043100.nut:
// simply trigger the game-over sequence with the default jingle.
ev42043100_30 <- function ()
{
	GameOver();
};

// Custom event step, styled like the game's own numbered event-step functions:
// trigger Game Over with a jingle other than the default "evt_006"
// (jingle ID here is illustrative, not a verified in-game asset name).
myEvent_GameOverStep <- function ()
{
	GameOver("evt_alt_defeat");
};
